section.code:
data Nat { Zero, // 1-cell: nullary constructor (generator) Succ(n: Nat), // 1-cell: field-tuple constructor
op add(m: Nat, n: Nat) -> Nat, // reserved: a defined operation (non-constructor symbol)
rule add(Zero, n) ~> n, // reserved 2-cell: a directed reduction (lhs ~> rhs) rule add(Succ(m), n) ~> Succ(add(m, n)), }
